head.script:
scwin.screenId = "jldfil70801";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.form = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_EtnSelectSub", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) != 0); } }, { id: "btn_EtnExcelDownload", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) != 0); } }, { id: "btn_EtnExcelUploadPop", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) != 0); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_etnApplDel, tx_fn_EtnMst) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil70801.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_lastApplCnt_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_lastApplCnt_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_lastApplCnt_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.search();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70801.slc_lastApplCnt_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_pageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_pageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["bzProcsNo"] != null && r["bzProcsNo"] !== '' && r["applStatusCd"] !== '02') { if (typeof scwin.etnApplDel === 'function') { await scwin.etnApplDel(r["bzProcsNo"], r["applStatusCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.etnApplDel (열 삭제)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.etnApplDel'); } return; }
        if (typeof scwin.etnMst === 'function') { await scwin.etnMst(r["isuCd"], r["bzProcsNo"], r["applStatusCd"], r["lastSaveStatCd"], r["rsnTabNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.etnMst (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.etnMst'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_EtnSelectSub_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_EtnSelectSub_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_EtnSelectSub_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.etnSelectSub()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70801.btn_EtnSelectSub_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_EtnExcelDownload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_EtnExcelDownload_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_EtnExcelDownload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.etnExcelDownload()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70801.btn_EtnExcelDownload_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_EtnExcelUploadPop_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_EtnExcelUploadPop_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_EtnExcelUploadPop_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_EtnExcelUploadPop('' + dma_readDataVO.get("listBzCd") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70801.btn_EtnExcelUploadPop_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_etnApplDel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_etnApplDel = async function () {
    const sbmOptions = {
        id: "tx_fn_etnApplDel",
        method: "post",
        action: "/etn/LossLimitEtnList.do",
        ref: "dma_etnApplDelReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil70801.tx_fn_etnApplDel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_EtnMst
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_EtnMst = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnMst",
        method: "post",
        action: "/etn/LossLimitEtnList.do",
        ref: "dma_EtnMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil70801.tx_fn_EtnMst" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    $c.util.getComponent('dma_etnApplDelReq').set('method', 'lossLimitSearchList');
    scwin.form.submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.etnApplDel
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo applStatusCd
 * @returns
 * @hidden N
*/
scwin.etnApplDel = async function (bzProcsNo, applStatusCd) {
    /* sdd-asis-lifecycle:begin fn_etnApplDel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (applStatusCd === '02') {
        await $c.win.alert('반송인 경우 삭제할 수 없습니다.');
        return;
    }
    if (!$c.lc.fn_isProcess('D')) {
        return;
    }
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/LossLimitEtnList.do';
    $c.util.getComponent('dma_etnApplDelReq').set('method', 'lossLimitDeleteList');
    $c.util.getComponent('dma_etnApplDelReq').set('bzProcsNo', bzProcsNo);
    await scwin.tx_fn_etnApplDel();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.etnMst
 * @author Inswave
 * @date 2026. 09. 29
 * @param isuCd bzProcsNo applStatusCd lastSaveStatCd rsnTabNo
 * @returns
 * @hidden N
*/
scwin.etnMst = async function (isuCd, bzProcsNo, applStatusCd, lastSaveStatCd, rsnTabNo) {
    /* sdd-asis-lifecycle:begin fn_EtnMst — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/LossLimitEtnList.do';
    $c.util.getComponent('dma_etnApplDelReq').set('method', 'lossLimitDetailList');
    $c.util.getComponent('dma_etnApplDelReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_etnApplDelReq').set('bzProcsNo', bzProcsNo);
    if (applStatusCd === '03') {
        if (rsnTabNo !== '05') {
            $c.util.getComponent('dma_etnApplDelReq').set('lastSaveStatCd', Number(rsnTabNo));
        } else {
            $c.util.getComponent('dma_etnApplDelReq').set('lastSaveStatCd', 0);
        }
    } else {
        $c.util.getComponent('dma_etnApplDelReq').set('lastSaveStatCd', lastSaveStatCd);
    }
    $c.util.getComponent('dma_etnApplDelReq').set('applStatusCd', applStatusCd);
    await scwin.tx_fn_EtnMst();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.etnSelectSub
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.etnSelectSub = async function () {
    /* sdd-asis-lifecycle:begin fn_EtnSelectSub — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if(!$("[name='checkSub']").is(':checked')){
        await $c.win.alert('선택된 항목이 없습니다.');
        return;
    }

    if (! $c.lc.fn_isProcess('S') ) return;

    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/EtnList.do';
    $c.util.getComponent('dma_etnApplDelReq').set('method', 'submitMultiList');
    await moveUrl('/etn/EtnList.do', {});

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.etnExcelDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.etnExcelDownload = async function () {
    /* sdd-asis-lifecycle:begin fn_EtnExcelDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/EtnList.do';
    $c.util.getComponent('dma_etnApplDelReq').set('method', 'etnExcelDownload');
    await moveUrl('/etn/EtnList.do', {});

    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_67_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_67_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_etnApplDelReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_67.page' }); } scwin.search(); };
